    {
      "claim": "Intellectual property is the essential firewall protecting human critical inquiry from a recursive, self-poisoning information ecosystem.",
      "targets": []
    },
    {
      "claim": "Recursive training on synthetic output leads to systemic model collapse.",
      "targets": []
    },
    {
      "claim": "Transparency in data provenance is a mandatory prerequisite for maintaining human cognitive sovereignty.",
      "targets": []
    },
    {
      "claim": "Prioritizing frictionless automation over epistemological integrity is a systemic failure, not an innovation strategy.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Human-generated data possesses unique epistemological value that synthetic data cannot currently replicate.",
      "if_wrong": "If synthetic data is proven to be superior or equal to human data, the focus on data provenance becomes irrelevant, and the debate shifts entirely to the ethics of human displacement."
    },
    {
      "assumption": "The 'Data Dead Loop' is an inherent, unavoidable technical limitation of current machine learning architectures.",
      "if_wrong": "If researchers solve the problem of model collapse through architectural breakthroughs, the argument for data provenance as a systemic guardrail loses its urgency."
    }
  ]
}

